/* pkcs7_new() doesn't check that the private key belongs to the certificate. A signature made with
 * another key fails to verify when the image is activated. */
if (sym_EVP_PKEY_eq(sym_X509_get0_pubkey(context->certificate), context->private_key) != 1)
        return log_error_errno(SYNTHETIC_ERRNO(EINVAL), "Private key does not match the certificate.");

/* PKCS7_sign() signs with a random nonce for ECDSA keys. The signature then differs on every build.
 * We set up the signer info with pkcs7_new() instead and sign with digest_and_sign(), which uses
 * deterministic nonces (RFC 6979) if the key supports them. Without signed attributes,
 * PKCS7_sign() signs the digest of the content the same way, so a signature with an RSA key stays
 * the same. */
PKCS7_SIGNER_INFO *si;
r = pkcs7_new(context->certificate, context->private_key, "SHA256", &p7, &si);
if (r < 0)
        return log_error_errno(r, "Failed to set up PKCS7 signature: %m");

if (sym_PKCS7_set_detached(p7, true) == 0)
        return log_openssl_errors(LOG_ERR, "Failed to set PKCS7 detached attribute");

_cleanup_free_ void *enc_digest = NULL;
size_t enc_digest_size;
r = digest_and_sign(sym_EVP_sha256(), context->private_key, hex, SIZE_MAX, &enc_digest, &enc_digest_size);
if (r < 0)
        return log_error_errno(r, "Failed to calculate PKCS7 signature: %m");
if (enc_digest_size > INT_MAX)
        return log_error_errno(SYNTHETIC_ERRNO(E2BIG), "PKCS7 signature too large.");

static PyObject *
zoneinfo_ZoneInfo(PyTypeObject *type, PyObject *args, PyObject *kwargs)
{
    return zoneinfo_ZoneInfo_helper(type, _PyTuple_CAST(args)->ob_item,
        PyTuple_GET_SIZE(args),
        kwargs ? PyDict_GET_SIZE(kwargs) : 0,
        kwargs, NULL);
}

static PyObject *
zoneinfo_ZoneInfo_vectorcall(PyObject *type, PyObject *const *args,
    size_t nargsf, PyObject *kwnames)
{
    PyObject *return_value = NULL;
    Py_ssize_t nargs = PyVectorcall_NARGS(nargsf);
    PyObject *key;

    assert(_PyType_CAST(type)->tp_new == zoneinfo_ZoneInfo);
    /* Make sure the type object is immutable: the generated
     * vectorcall doesn't deal e.g. with users reassigning __init__. */
    assert(PyType_HasFeature(_PyType_CAST(type), Py_TPFLAGS_IMMUTABLETYPE));
    if (kwnames != NULL || nargs < 1 || nargs > 1) {
        return zoneinfo_ZoneInfo_helper(_PyType_CAST(type), args, nargs,
            kwnames ? PyTuple_GET_SIZE(kwnames) : 0,
            NULL, kwnames);
    }
    key = args[0];
    Py_BEGIN_CRITICAL_SECTION(type);
    return_value = zoneinfo_ZoneInfo_impl(_PyType_CAST(type), key);
    Py_END_CRITICAL_SECTION();

    return return_value;
}

// Only after including descendants' ranges can we tell whether a body
// really has no executable code. Discovery in imap alone is insufficient:
// positions on zero-width instructions can discover a range-less inline.
// Give such bodies the range of their retained call-site instruction.
// Leave surviving bodies' ranges alone.
empty := make([]bool, len(inlcalls.Calls))
for i, c := range inlcalls.Calls {
	empty[i] = len(c.Ranges) == 0
}
addedAnchor := false
for _, mark := range fnsym.Func().InlMarks {
	idx := imap[int(mark.Index())]
	if !empty[idx] {
		continue
	}
	p := mark.Prog()
	end := fnsym.Size
	for q := p.Link; q != nil; q = q.Link {
		if q.Pc > p.Pc {
			end = q.Pc
			break
		}
	}
	if end > p.Pc {
		inlcalls.Calls[idx].Ranges = append(inlcalls.Calls[idx].Ranges,
			dwarf.Range{Start: p.Pc, End: end})
		addedAnchor = true
	}
}
if addedAnchor {
	for i := range inlcalls.Calls {
		ranges := inlcalls.Calls[i].Ranges
		slices.SortFunc(ranges, func(a, b dwarf.Range) int {
			return cmp.Compare(a.Start, b.Start)
		})
		inlcalls.Calls[i].Ranges = dwarf.MergeRanges(ranges, nil)
	}
	for k, c := range inlcalls.Calls {
		if c.Root {
			unifyCallRanges(inlcalls, k)
		}
	}
}

/**
 * @brief The largest workspace size ?gelsd, ?gelsy or ?gelss computes for an m-by-n system.
 *
 * Mirrors the sizes Reference-LAPACK evaluates, see "Workspace sizes that LAPACK computes
 * itself" in _common_array_utils.hpp.
 *
 * @tparam T      Element type; the complex ?gelsd also computes the size of its real workspace.
 * @param m       Number of rows.
 * @param n       Number of columns.
 * @param nrhs    Number of right-hand sides.
 * @param ldb     Leading dimension of b, max(1, m, n).
 * @param driver  The LAPACK routine.
 * @return The largest size, evaluated without overflow.
 */
template<typename T>
std::uint64_t
lstsq_max_work_size(const std::uint64_t m, const std::uint64_t n, const std::uint64_t nrhs,
                    const std::uint64_t ldb, const LstsqDriver driver)
{
    const std::uint64_t k = std::min(m, n), kmax = std::max(m, n);
    // ILAENV(1, ...) block size of the routines each driver calls: 64 for the ?TZRZF and ?ORMRZ
    // of gelsy, 32 for the others
    const std::uint64_t nb = (driver == LstsqDriver::gelsy) ? 64 : 32;
    const std::uint64_t smlsiz = 25;    // ILAENV(9, ...), the size of the subproblems in gelsd
    // NLVL = MAX(INT(LOG2(min(m, n) / (smlsiz + 1))) + 1, 0), truncating towards zero
    const long lvl = (k > 0) ? (long)std::log2(double(k) / double(smlsiz + 1)) + 1 : 0;
    const std::uint64_t nlvl = lvl > 0 ? (std::uint64_t)lvl : 0;
    // n >= MNTHR = ILAENV(6, ...) = INT(1.6 * min(m, n)) selects the LQ path when m < n
    const bool lq_path = (m < n) && n >= (std::uint64_t)(float(m) * 1.6f);

    // the block-size terms: (m + n)*nb from the bidiagonal or QR stage, nrhs*nb from applying
    // the orthogonal factors to b
    std::uint64_t need = 3*kmax + 2*k + nb*std::max(m + n + 1, nrhs);
    if (driver == LstsqDriver::gelsd) {
        const std::uint64_t wlalsd = 9*k + 2*k*smlsiz + 8*k*nlvl + k*nrhs + (smlsiz + 1)*(smlsiz + 1);
        need = std::max(need, 3*k + wlalsd);
        if (lq_path) { need = std::max(need, m*m + 4*m + std::max(wlalsd, m*nrhs + m)); }
        if constexpr (is_complex_v<T>) {
            // the complex gelsd computes the size of its real workspace rwork as well
            const std::uint64_t lrwork = 10*k + 2*k*smlsiz + 8*k*nlvl + 3*smlsiz*nrhs +
                                         std::max((smlsiz + 1)*(smlsiz + 1), n*(1 + nrhs) + 2*nrhs);
            need = std::max(need, lrwork);
        }
    } else if (driver == LstsqDriver::gelss) {
        // gelss also compares lwork with ldb*nrhs to choose its path
        need = std::max(need, ldb*nrhs + 4*kmax + k);
        if (lq_path) { need = std::max(need, m*m + 4*m + std::max({m, nrhs, n}) + m*nrhs); }
    }
    return need;
}

// Ported from ideep::convolution_transpose_forward::do_prepare.
// For int8
template <bool with_bias>
void do_prepare(
    deconv_forward_params& param,
    const ideep::tensor& src,
    const ideep::tensor& weights,
    const ideep::tensor& bias,
    const dnnl::memory::dims& dst_dims,
    ideep::tensor& dst,
    const dnnl::memory::dims& strides,
    const dnnl::memory::dims& dilates,
    const dnnl::memory::dims& padding_l,
    const dnnl::memory::dims& padding_r,
    int groups,
    const std::vector<float>& src_scales,
    const std::vector<float>& weights_scales,
    const std::vector<float>& dst_scales,
    const std::vector<int32_t>& src_zero_point,
    const std::vector<int32_t>& dst_zero_point,
    bool is_channels_last,
    const ideep::attr_t& attr,
    dnnl::algorithm aalgorithm,
    dnnl::prop_kind aprop_kind,
    const ideep::lowp_kind alowp_kind) {
  ideep::tensor::desc src_desc, weights_desc, bias_desc, dst_desc;
  ideep::attr_t op_attr, src_attr, weights_attr, bias_attr;
  ideep::tensor weights_grouped;
  dnnl::memory::dims dil_compatible;

  prepare_parameters(
      src,
      weights,
      bias,
      dst_dims,
      dst,
      dilates,
      groups,
      src_scales,
      weights_scales,
      dst_scales,
      src_zero_point,
      dst_zero_point,
      attr,
      alowp_kind,
      with_bias,
      /*is_deconv=*/true,
      weights_grouped,
      dil_compatible,
      op_attr,
      src_attr,
      weights_attr,
      bias_attr,
      src_desc,
      weights_desc,
      bias_desc,
      dst_desc);

  param.pd = get_primitive_desc<with_bias>(
      src_desc,
      weights_desc,
      bias_desc,
      dst_desc,
      strides,
      dil_compatible,
      padding_l,
      padding_r,
      is_channels_last,
      op_attr,
      aalgorithm,
      aprop_kind);

  param.primitive = dnnl::deconvolution_forward(param.pd);
  param.op_attr = std::move(op_attr);
  param.bias_attr = std::move(bias_attr);
  param.groups = groups;

  // Prepare tensors for scales and zero points
  if (param.op_attr.has_scales()) {
    if (!param.all_scales) {
      param.all_scales.reset(new std::unordered_map<int, ideep::tensor>);
    }
    for (auto& arg_scale_pair : param.op_attr.get_all_scales()) {
      int dnnl_arg = arg_scale_pair.first;
      const std::vector<float>& scale = arg_scale_pair.second.first;
      ideep::tensor scales_m(scale);
      param.all_scales->insert({dnnl_arg, scales_m});
    }
  }
  if (param.op_attr.has_zero_points()) {
    if (!param.all_zero_points) {
      param.all_zero_points.reset(new std::unordered_map<int, ideep::tensor>);
    }
    for (auto& arg_zp_pair : param.op_attr.get_all_zero_points()) {
      int dnnl_arg = arg_zp_pair.first;
      const std::vector<int32_t>& zp = arg_zp_pair.second.first;
      ideep::tensor zp_m(zp);
      param.all_zero_points->insert({dnnl_arg, zp_m});
    }
  }
}

