impl<K, V> MallocSizeOf for hashlink::LruCache<K, V>
where
    K: Eq + Hash + MallocSizeOf,
    V: MallocSizeOf,
{
    fn size_of(&self, ops: &mut MallocSizeOfOps) -> usize {
        // LruCache is a wrapper around LinkedHashMap, which unfortunately does not expose capacity.
        let pointer_size = size_of::<*const ()>();
        self.iter()
            .map(|(key, value)| {
                // We estimate the size here by assuming that each LinkedHashMap entry costs the
                // slot itself plus one pointers for each of the two links, and then the size of the
                // key and value.
                (3 * pointer_size) + size_of::<(K, V)>() + key.size_of(ops) + value.size_of(ops)
            })
            .sum()
    }
}

impl<K, V> MallocConditionalSizeOf for hashlink::LruCache<K, V>
where
    K: Eq + Hash + MallocConditionalSizeOf,
    V: MallocConditionalSizeOf,
{
    fn conditional_size_of(&self, ops: &mut MallocSizeOfOps) -> usize {
        // LruCache is a wrapper around LinkedHashMap, which unfortunately does not expose capacity.
        let pointer_size = size_of::<*const ()>();
        self.iter()
            .map(|(key, value)| {
                // We estimate the size here by assuming that each LinkedHashMap entry costs the
                // slot itself plus one pointers for each of the two links, and then the size of the
                // key and value.
                (3 * pointer_size) +
                    size_of::<(K, V)>() +
                    key.conditional_size_of(ops) +
                    value.conditional_size_of(ops)
            })
            .sum()
    }
}

static PyObject *
memoryview(PyTypeObject *type, PyObject *args, PyObject *kwargs)
{
    return memoryview_helper(type, _PyTuple_CAST(args)->ob_item,
        PyTuple_GET_SIZE(args),
        kwargs ? PyDict_GET_SIZE(kwargs) : 0,
        kwargs, NULL);
}

static PyObject *
memoryview_vectorcall(PyObject *type, PyObject *const *args,
    size_t nargsf, PyObject *kwnames)
{
    PyObject *return_value = NULL;
    Py_ssize_t nargs = PyVectorcall_NARGS(nargsf);
    PyObject *object;

    assert(_PyType_CAST(type)->tp_new == memoryview);
    /* Make sure the type object is immutable: the generated
     * vectorcall doesn't deal e.g. with users reassigning __init__. */
    assert(PyType_HasFeature(_PyType_CAST(type), Py_TPFLAGS_IMMUTABLETYPE));
    if (kwnames != NULL || nargs < 1 || nargs > 1) {
        return memoryview_helper(_PyType_CAST(type), args, nargs,
            kwnames ? PyTuple_GET_SIZE(kwnames) : 0,
            NULL, kwnames);
    }
    object = args[0];
    return_value = memoryview_impl(_PyType_CAST(type), object);

    return return_value;
}

// Ported from ideep::convolution_forward::do_prepare.
