/*
 * Casts a single-operand view to 'dtype' and copies it into 'out', for those that are given.
 * Steals a reference to 'view'. Returns a new reference to the result, or NULL on error.
 */
static PyArrayObject *
finish_single_op_view(PyArrayObject *view, PyArrayObject *out,
                      PyArray_Descr *dtype, NPY_CASTING casting)
{
    PyArrayObject *ret = NULL;

    /* AssignArray does not check this when 'out' is identical to the view */
    if (out != NULL && PyArray_FailUnlessWriteable(out, "output array") < 0) {
        goto finish;
    }
    if (dtype != NULL) {
        /* Sizes an unsized dtype such as str from the view */
        dtype = PyArray_AdaptDescriptorToArray(view, NULL, dtype);
        if (dtype == NULL) {
            goto finish;
        }
        npy_intp view_offset = NPY_MIN_INTP;
        if (PyArray_SafeCast(PyArray_DESCR(view), dtype, &view_offset,
                             NPY_NO_CASTING, 1) && view_offset == 0) {
            Py_CLEAR(dtype);
        }
        else if (out == NULL && !PyArray_CanCastArrayTo(view, dtype, casting)) {
            Py_DECREF(dtype);
            dtype = NULL;
            /* Deprecated NumPy 2.6, 2026-11-23 */
            if (PyErr_WarnEx(PyExc_DeprecationWarning,
                    "einsum ignored `dtype` and returned a view of the operand because "
                    "`casting` does not allow the cast. This will raise a TypeError in "
                    "the future. (Deprecated NumPy 2.6)", 2) < 0) {
                goto finish;
            }
        }
    }
    /*
     * AssignArray skips its overlap copy for same-direction 1-D strides,
     * even when a diagonal and 'out' have different strides.
     */
    if (dtype != NULL || (out != NULL && arrays_overlap(view, out))) {
        PyArrayObject *tmp = (PyArrayObject *)PyArray_NewLikeArray(
                view, NPY_KEEPORDER, dtype, out == NULL);
        if (tmp != NULL && PyArray_AssignArray(tmp, view, NULL, casting) < 0) {
            Py_CLEAR(tmp);
        }
        Py_SETREF(view, tmp);
        if (view == NULL) {
            goto finish;
        }
    }
    if (out == NULL) {
        ret = view;
        view = NULL;
        goto finish;
    }
    if (PyArray_AssignArray(out, view, NULL, casting) < 0) {
        goto finish;
    }
    Py_INCREF(out);
    ret = out;

  finish:
    Py_XDECREF(view);
    return ret;
}

#[gpui::test]
async fn test_ctrl_hover_in_mouse_mode(cx: &mut TestAppContext) {
    let (test_entities, hovered_word, cx) =
        init_ctrl_hover_hyperlink_test_with_window(cx).await;
    let steps: [(fn(&mut HyperlinkVisualTestContext), Option<HoveredWord>); 8] = [
        (
            |cx| cx.terminal.write_output(b"\x1b[?1002h", cx.cx),
            Some(hovered_word.clone()),
        ),
        (|cx| cx.ctrl_mouse_move_to(point(px(2.5), px(2.5))), None),
        (
            |cx| cx.ctrl_mouse_move_to(ZED_DEV_PT),
            Some(hovered_word.with_id(1)),
        ),
        (
            |cx| cx.ctrl_mouse_move(ZED_DEV_PT, Some(MouseButton::Left)),
            None,
        ),
        (
            |cx| {
                ctrl_mouse_down_at(cx.terminal, ZED_DEV_PT, cx.cx);
                cx.ctrl_mouse_move(ZED_DEV_PT, Some(MouseButton::Left));
            },
            Some(hovered_word.with_id(2)),
        ),
        (
            |cx| {
                cx.cx
                    .update_global(|store: &mut settings::SettingsStore, cx| {
                        store.update_user_settings(cx, |settings| {
                            settings
                                .terminal
                                .get_or_insert_default()
                                .open_links_in_mouse_mode = Some(false);
                        });
                    });
                cx.try_modifiers_change(Modifiers::secondary_key(cx.cx));
            },
            None,
        ),
        (|cx| cx.ctrl_mouse_move_to(ZED_DEV_PT), None),
        (|cx| cx.write_output_lines(OUTPUT_ZED_DEV, 8), None),
    ];
    for (index, (step, expected)) in steps.into_iter().enumerate() {
        update_test_entities(&test_entities, cx, |cx| {
            step(cx);
            None
        });
        update_test_entities(&test_entities, cx, |cx| {
            let content = &cx.terminal.last_content;
            assert!(content.mode.intersects(Modes::MOUSE_MODE), "step {index}");
            assert_eq!(content.last_hovered_word, expected, "step {index}");
            None
        });
    }
}

