func archAvailableIEEE() bool {
	return cpu.RISCV64.HasZbc
}

var archIeeeTable8 *slicing8Table

func archInitIEEE() {
	if !cpu.RISCV64.HasZbc {
		panic("arch-specific zbc instruction for IEEE not available")
	}
	// The slicing-by-8 table is used for byte-at-a-time alignment (inside the
	// CLMUL routine) and for the tail that does not form a complete 16-byte
	// block. It is also the fallback for inputs shorter than 16 bytes.
	archIeeeTable8 = slicingMakeTable(IEEE)
}

func archUpdateIEEE(crc uint32, p []byte) uint32 {
	if !cpu.RISCV64.HasZbc {
		panic("arch-specific zbc instruction for IEEE not available")
	}

	// The CLMUL routine byte-aligns the input to a 16-byte boundary before
	// the fold loop, so it is safe on cores that trap on unaligned accesses.
	// Give it all complete 16-byte blocks.
	if len(p) >= 16 {
		aligned := len(p) &^ 15
		crc = ^ieeeUpdateCLMUL(^crc, &archIeeeTable8[0], p[:aligned])
		p = p[aligned:]
	}
	if len(p) == 0 {
		return crc
	}
	return slicingUpdate(crc, archIeeeTable8, p)
}

func archAvailableCastagnoli() bool {
	return cpu.RISCV64.HasZbc
}

var archCastagnoliTable8 *slicing8Table

func archInitCastagnoli() {
	if !cpu.RISCV64.HasZbc {
		panic("arch-specific zbc instruction for Castagnoli not available")
	}
	// The slicing-by-8 table is used for byte-at-a-time alignment (inside the
	// CLMUL routine) and for the tail that does not form a complete 16-byte
	// block. It is also the fallback for inputs shorter than 16 bytes.
	archCastagnoliTable8 = slicingMakeTable(Castagnoli)
}

func archUpdateCastagnoli(crc uint32, p []byte) uint32 {
	if !cpu.RISCV64.HasZbc {
		panic("arch-specific zbc instruction for Castagnoli not available")
	}

	// Same as archUpdateIEEE.
	if len(p) >= 16 {
		aligned := len(p) &^ 15
		crc = ^castagnoliUpdateCLMUL(^crc, &archCastagnoliTable8[0], p[:aligned])
		p = p[aligned:]
	}
	if len(p) == 0 {
		return crc
	}
	return slicingUpdate(crc, archCastagnoliTable8, p)
}

void CheckDecimalWidthV2(CV2Factory &factory, const LogicalType &type) {
	auto context = factory.TryGetClientContext();
	const uint32_t limit = context ? DecimalWidthLimit::FromSetting(context).width : Decimal::DEFAULT_MAX_WIDTH;
	TypeVisitor::Contains(type, [&](const LogicalType &child) {
		if (child.id() != LogicalTypeId::DECIMAL || DecimalType::GetWidth(child) <= limit) {
			return false;
		}
		if (context) {
			throw InvalidInputException(
			    "DECIMAL width %u exceeds the maximum DECIMAL width of %u (SET max_decimal_width to allow wider "
			    "decimals)",
			    DecimalType::GetWidth(child), limit);
		}
		throw InvalidInputException(
		    "DECIMAL width %u exceeds the maximum DECIMAL width of %u: a factory without a connection creates decimals "
		    "up to the default of max_decimal_width, use the factory of a connection that raised the setting for wider "
		    "decimals",
		    DecimalType::GetWidth(child), limit);
	});
}

def _get_multidict_extras(
    received_params: Mapping[str, Any], processed_keys: set[str]
) -> Iterator[tuple[str, Any]]:
    if isinstance(received_params, ImmutableMultiDict):
        # Unlike items(), multi_items() preserves duplicate query and form keys.
        items = received_params.multi_items()
    elif isinstance(received_params, Headers):
        # Headers.items() already includes every occurrence of each header.
        items = received_params.items()
    else:
        for key in received_params:
            if key not in processed_keys:
                yield key, received_params.get(key)
        return

    # Group repeated values once instead of scanning all entries for every key.
    grouped: dict[str, list[Any]] = {}
    for key, value in items:
        if key not in processed_keys:
            grouped.setdefault(key, []).append(value)
    for key, values in grouped.items():
        yield key, values[0] if len(values) == 1 else values

static int invalidate_stale_dirs(struct untracked_cache *uc,
				 struct untracked_cache_dir *ucd,
				 struct index_state *istate,
				 struct strbuf *path)
{
	struct stat st;
	size_t len = path->len;
	int nr_invalidated = 0;
	unsigned int i;

	if (ucd->valid &&
	    (lstat(path->buf, &st) ||
	     match_stat_data_racy(istate, &ucd->stat_data, &st))) {
		invalidate_one_directory(uc, ucd);
		nr_invalidated++;
	}

	for (i = 0; i < ucd->dirs_nr; i++) {
		/* not written to the index, see write_one_dir() */
		if (!ucd->dirs[i]->recurse)
			continue;
		strbuf_addch(path, '/');
		strbuf_addstr(path, ucd->dirs[i]->name);
		nr_invalidated += invalidate_stale_dirs(uc, ucd->dirs[i],
							istate, path);
		strbuf_setlen(path, len);
	}

	return nr_invalidated;
}

int untracked_cache_invalidate_stale_dirs(struct index_state *istate)
{
	struct strbuf path = STRBUF_INIT;
	const char *worktree;
	int nr_invalidated;

	if (!istate->untracked || !istate->untracked->root)
		return 0;

	/*
	 * The index is also read and written by commands that do not
	 * run in the top-level directory of the worktree.
	 */
	worktree = repo_get_work_tree(istate->repo);
	if (!worktree) {
		invalidate_directory(istate->untracked,
				     istate->untracked->root);
		return 1;
	}

	strbuf_addstr(&path, worktree);
	nr_invalidated = invalidate_stale_dirs(istate->untracked,
					       istate->untracked->root,
					       istate, &path);
	strbuf_release(&path);
	return nr_invalidated;
}

// Describes what the main thread was doing and what keeps the event loop
// alive. This must not call into JavaScript, as it may run from a V8 interrupt.
std::string FormatProcessTimeoutDiagnostics(Environment* env) {
  Isolate* isolate = env->isolate();
  std::string result;

  Local<StackTrace> stack;
  if (GetCurrentStackTrace(isolate, static_cast<int>(env->stack_trace_limit()))
          .ToLocal(&stack) &&
      stack->GetFrameCount() > 0) {
    result += "Main thread was executing JavaScript:\n";
    result += FormatJavaScriptStack(isolate, stack);
  } else {
    result += "Main thread was not executing JavaScript.\n";
  }
  return result + FormatResources(env, "the");
}

