def _validate_scalar_rows(data: list[Any]) -> list[bool]:
    # GH#29213 a non-iterable row would otherwise fail later with an opaque error;
    #  a null row after a tuple row is padded by lib.to_object_array_tuples.
    #  Returns whether each row is such a null row.
    allow_null = isinstance(data[0], tuple)
    null_rows = []
    for i, row in enumerate(data):
        is_null = allow_null and is_scalar(row) and isna(row)
        null_rows.append(is_null)
        if is_null:
            continue
        try:
            iter(row)
        except TypeError as err:
            raise TypeError(
                "When the first row is list-like, every row must be list-like, "
                f"but the row at position {i} has type {type(row).__name__}. To "
                "store list-likes as values of a single column, construct a "
                "Series and call to_frame() instead."
            ) from err
    return null_rows

#!/usr/bin/env python3
"""
Remove the files of git submodules that NumPy does not need from an sdist.

Run by ``meson dist``. Every submodule needs an entry in `UNUSED`, so that
none is added without a decision on what the sdist carries of it.
"""
import os
import re
import shutil

# What to remove from each submodule: documentation, tests, benchmarks and
# CI files. An empty list keeps all of it.
UNUSED = {
    'doc/source/_static/scipy-mathjax': [],
    'numpy/_core/src/common/pythoncapi-compat': ['docs', 'tests'],
    'numpy/_core/src/highway': [
        'docs', 'g3doc', 'hwy/examples', 'hwy/tests',
    ],
    'numpy/_core/src/npysort/x86-simd-sort': [
        'benchmarks', 'examples', 'misc', 'tests',
    ],
    'numpy/_core/src/umath/svml': [],
    'numpy/fft/pocketfft': [],
    'vendored-meson/meson': [
        'docs', 'graphics', 'manual tests', 'test cases', 'unittests',
    ],
}


def main():
    root = os.environ['MESON_DIST_ROOT']
    with open(os.path.join(root, '.gitmodules')) as f:
        submodules = set(re.findall(r'^\s*path\s*=\s*(\S+)', f.read(), re.M))
    if submodules != set(UNUSED):
        changed = ', '.join(sorted(submodules ^ set(UNUSED)))
        raise SystemExit(f"{__file__}: `UNUSED` needs an update for {changed}")

    for path, entries in UNUSED.items():
        for name in entries:
            entry = os.path.join(root, path, name)
            if os.path.isdir(entry) and not os.path.islink(entry):
                shutil.rmtree(entry)
            else:
                # fails if the entry is gone, so that the lists do not go stale
                os.remove(entry)


if __name__ == "__main__":
    main()

class StrBuiltinVariable(TypeVariable):
    _fn = str

    tp_methods = {
        "maketrans": _constant_fold_classmethod("maketrans"),
    }

    @_constant_fold_on_unsupported
    def call_function(
        self,
        tx: "InstructionTranslatorBase",
        args: list[VariableTracker],
        kwargs: dict[str, VariableTracker],
    ) -> VariableTracker:
        if not args and not kwargs:
            return ConstantVariable.create("")
        if len(args) == 1 and not kwargs:
            # str(a) on a lazy constant stays lazy; generic_str would realize
            # it and guard on its value.
            result = _try_computed_lazy_constant(str, args)
            if result is not None:
                return result
            return generic_str(tx, args[0])
        return constant_fold(self._fn, tx, args, kwargs)


