/*
 * Check that the string refname matches a rule of the form
 * "{prefix}%.*s{suffix}". So "foo/bar/baz" would match the rule
 * "foo/%.*s/baz", and return the string "bar".
 */
static const char *match_parse_rule(const char *refname, const char *rule,
				    size_t *len)
{
	/*
	 * Check that rule matches refname up to the first percent in the rule.
	 * We can bail immediately if not, but otherwise we leave "rule" at the
	 * %-placeholder, and "refname" at the start of the potential matched
	 * name.
	 */
	while (*rule != '%') {
		if (!*rule)
			BUG("rev-parse rule did not have percent");
		if (*refname++ != *rule++)
			return NULL;
	}

	/*
	 * Check that our "%" is the expected placeholder. This assumes there
	 * are no other percents (placeholder or quoted) in the string, but
	 * that is sufficient for our rev-parse rules.
	 */
	if (!skip_prefix(rule, "%.*s", &rule))
		return NULL;

	/*
	 * And now check that our suffix (if any) matches.
	 */
	if (!strip_suffix(refname, rule, len))
		return NULL;

	return refname; /* len set by strip_suffix() */
}

struct refspec_match {
	struct ref *matched_weak;
	struct ref *matched;
	int weak_match;
	int match;
};

static void add_refspec_match(struct refspec_match *m, const char *pattern,
			      struct ref *ref)
{
	size_t patlen = strlen(pattern);
	size_t namelen = strlen(ref->name);

	/* A match is "weak" if it is with refs outside
	 * heads or tags, and did not specify the pattern
	 * in full (e.g. "refs/remotes/origin/master") or at
	 * least from the toplevel (e.g. "remotes/origin/master");
	 * otherwise "git push $URL master" would result in
	 * ambiguity between remotes/origin/master and heads/master
	 * at the remote site.
	 */
	if (namelen != patlen &&
	    patlen != namelen - 5 &&
	    !starts_with(ref->name, "refs/heads/") &&
	    !starts_with(ref->name, "refs/tags/")) {
		/* We want to catch the case where only weak
		 * matches are found and there are multiple
		 * matches, and where more than one strong
		 * matches are found, as ambiguous.  One
		 * strong match with zero or more weak matches
		 * are acceptable as a unique match.
		 */
		m->matched_weak = ref;
		m->weak_match++;
	} else {
		m->matched = ref;
		m->match++;
	}
}

static int finish_refspec_match(const struct refspec_match *m,
				struct ref **matched_ref)
{
	if (!m->matched) {
		if (matched_ref)
			*matched_ref = m->matched_weak;
		return m->weak_match;
	}
	if (matched_ref)
		*matched_ref = m->matched;
	return m->match;
}

/* Numeric keys keep their type, even for values outside their documented range.
 * location.role and rating.user are from the QuickTime File Format, the others
 * as in Apple files, e.g. the 8-byte type 21 of iPhone Live Photos.
 * full-frame-rate-playback-intent is written as Compressor does, some iPhone
 * recordings use type 21 with 8 bytes. */
static int mov_write_mdta_data_tag(AVIOContext *pb, const char *key, const char *value)
{
    static const struct {
        const char *key;
        int type; /* 21: BE signed, 22: BE unsigned, 23: BE float32 */
        int size;
    } numeric[] = {
        { "com.apple.quicktime.full-frame-rate-playback-intent",     22, 1 },
        { "com.apple.quicktime.live-photo.auto",                     22, 1 },
        { "com.apple.quicktime.live-photo.vitality-score",           23, 4 },
        { "com.apple.quicktime.live-photo.vitality-scoring-version", 21, 8 },
        { "com.apple.quicktime.location.role",                       22, 1 },
        { "com.apple.quicktime.rating.user",                         23, 4 },
    };

    for (int i = 0; i < FF_ARRAY_ELEMS(numeric); i++) {
        int type = numeric[i].type, size = numeric[i].size;
        int64_t v;

        if (strcmp(key, numeric[i].key))
            continue;
        if (type == 23) {
            float f;
            int len = 0;
            if (av_sscanf(value, "%f%n", &f, &len) != 1 || value[len] || !isfinite(f))
                break;
            /* the sign of -0 is lost with -fno-signed-zeros */
            v = av_float2int(f) | (value[strspn(value, " \t\n\v\f\r")] == '-' ? 0x80000000 : 0);
        } else {
            int64_t max = size == 8 ? INT64_MAX :
                          (INT64_C(1) << (8 * size - (type == 21))) - 1;
            int64_t min = type == 22 ? 0 : -max - 1;
            char buf[32], *end;
            v = strtoll(value, &end, 10);
            snprintf(buf, sizeof(buf), "%"PRId64, v);
            if (strcmp(buf, value) || v < min || v > max)
                break;
        }
        avio_wb32(pb, 16 + size); /* size */
        ffio_wfourcc(pb, "data");
        avio_wb32(pb, type);
        avio_wb32(pb, 0);
        for (int b = size - 1; b >= 0; b--)
            avio_w8(pb, v >> (8 * b) & 0xff);
        return 16 + size;
    }
    return mov_write_string_data_tag(pb, value, 0, 1);
}

/* An ACK write can fail while the replica is applying buffered
 * commands during full sync. Keep its upstream client alive so the
 * application loop can finish. Closing it now would discard received
 * commands and make PSYNC request them again from an older offset.
 * If that history has left the primary's backlog, another full sync
 * would be required. */
if (c->running_tid == IOTHREAD_MAIN_THREAD_ID &&
    c == server.master &&
    (server.repl_main_ch_state & REPL_MAIN_CH_STREAMING_BUF))
{
    /* Disable read and write callbacks while buffered commands are applied. */
    connSetWriteHandler(c->conn, NULL);
    connSetReadHandler(c->conn, NULL);
    /* Unlike CLIENT_CLOSE_ASAP, this flag lets buffer application
     * continue. Once it finishes, rdbChannelStreamReplDataToDb()
     * calls freeClient() to close the connection, cache the applied
     * offset and reconnect for PSYNC. */
    server.repl_main_ch_state |= REPL_MAIN_CH_CLOSE_ASAP;
} else {
    freeClientAsync(c);
}

@final
@cache_readonly
def _engine_target_is_object_cast(self) -> bool:
    """
    Whether _get_engine_target casts our ExtensionArray to an object ndarray.

    Lets callers tell whether the engine would be an object engine without
    building it.
    """
    vals = self._values
    if (
        type(self) is not Index
        or not isinstance(vals, ExtensionArray)
        or isinstance(vals, (BaseMaskedArray, StringArray))
    ):
        return False
    if isinstance(vals, ArrowExtensionArray):
        dtype = self.dtype
        if dtype.kind in "Mm":
            import pyarrow as pa

            pa_type = vals._pa_array.type
            if pa.types.is_timestamp(pa_type) or pa.types.is_duration(pa_type):
                return False
        # Numeric types other than decimal go to the engine as-is
        return not is_numeric_dtype(dtype) or dtype.kind == "O"
    # TODO(ExtensionIndex): remove special-case, just use self._values
    return True

/**
 * Samples a decoder started inside the stream outputs before its output is
 * exact: the synthesis history, then for layer III the IMDCT overlap and
 * the granules whose main data begins before the first frame decoded. The
 * bit reservoir reach is bounded for the smallest frames this stream format
 * allows, as an encoder may use all of it.
 */
static int seek_preroll(const MPADecodeHeader2 *hdr)
{
    const int synth_history = 512 - 32;
    const int imdct_overlap = 576;

    if (hdr->layer != 3)
        return synth_history;

    const int samples_per_frame   = hdr->lsf ? 576 : 1152;
    const int max_main_data_begin = hdr->lsf ? 255 : 511;
    const int side_info_size      = hdr->lsf ? (hdr->nb_channels == 1 ?  9 : 17)
                                             : (hdr->nb_channels == 1 ? 17 : 32);
    const int min_frame_size      = ff_mpa_bitrate_tab[hdr->lsf][2][1] * 144000 /
                                    (hdr->sample_rate << hdr->lsf);
    /* header and CRC */
    const int min_main_data       = min_frame_size - 4 - 2 - side_info_size;

    return synth_history + imdct_overlap +
           (max_main_data_begin + min_main_data - 1) / min_main_data *
           samples_per_frame;
}

def constant_fold(
    fn: Callable[..., object],
    tx: "InstructionTranslatorBase",
    args: list[VariableTracker],
    kwargs: dict[str, VariableTracker],
) -> VariableTracker:
    try:
        res = fn(
            *(a.as_python_constant() for a in args),
            **{k: v.as_python_constant() for k, v in kwargs.items()},
        )
    except Exception as e:
        raise_observed_exception(type(e), tx, args=list(e.args))
    return VariableTracker.build(tx, res)


def _constant_fold_classmethod(name: str) -> Method:
    """tp_methods entry for a classmethod of a builtin type (e.g. int.from_bytes)
    that is evaluated at trace time on constant arguments."""

    def handler(
        self: "TypeVariable",
        tx: "InstructionTranslatorBase",
        args: list[VariableTracker],
        kwargs: dict[str, VariableTracker],
    ) -> VariableTracker:
        return constant_fold(getattr(self._fn, name), tx, args, kwargs)

    return Method(handler)


def _constant_fold_on_unsupported(
    call_function: Callable[..., VariableTracker],
) -> Callable[..., VariableTracker]:
    """If the modeled path graph breaks on constant arguments, evaluate the call
    at trace time instead (e.g. int() of a pybind11 enum, whose C __int__ has no
    model)."""

    @functools.wraps(call_function)
    def wrapper(
        self: "TypeVariable",
        tx: "InstructionTranslatorBase",
        args: list[VariableTracker],
        kwargs: dict[str, VariableTracker],
    ) -> VariableTracker:
        try:
            return call_function(self, tx, args, kwargs)
        except Unsupported as exc:
            if not check_unspec_or_constant_args(args, kwargs):
                raise
            exc.remove_from_stats()
        return constant_fold(self._fn, tx, args, kwargs)

    return wrapper

class IntBuiltinVariable(TypeVariable):
    _fn = int

    tp_methods = {
        "from_bytes": _constant_fold_classmethod("from_bytes"),
    }

    @_constant_fold_on_unsupported
    def call_function(
        self,
        tx: "InstructionTranslatorBase",
        args: list[VariableTracker],
        kwargs: dict[str, VariableTracker],
    ) -> VariableTracker:
        # int(x=0, /, base=10)
        base = kwargs.get("base")
        for name in kwargs:
            if name != "base":
                raise_type_error(
                    tx, f"int() got an unexpected keyword argument '{name}'"
                )
        if len(args) > 2:
            raise_type_error(tx, f"int expected at most 2 arguments, got {len(args)}")
        if len(args) + (base is not None) > 2:
            raise_type_error(
                tx, f"int() takes at most 2 arguments ({len(args) + 1} given)"
            )
        if not args:
            if base is not None:
                raise_type_error(tx, "int() missing string argument")
            return ConstantVariable.create(0)
        if len(args) == 2:
            base = args[1]
        if base is None:
            return pynumber_int(tx, args[0])
        res = pylong_from_base(tx, args[0], base)
        if res is None:
            unimplemented(
                gb_type="int() with a base on non-constant arguments",
                context=f"int({args[0]}, {base})",
                explanation="Dynamo only traces int(x, base) when x and base are constants.",
                hints=[*graph_break_hints.SUPPORTABLE],
            )
        return res


class FloatBuiltinVariable(TypeVariable):
    _fn = float

    tp_methods = {"fromhex": _constant_fold_classmethod("fromhex")}
    if sys.version_info >= (3, 14):
        tp_methods["from_number"] = _constant_fold_classmethod("from_number")

    @_constant_fold_on_unsupported
    def call_function(
        self,
        tx: "InstructionTranslatorBase",
        args: list[VariableTracker],
        kwargs: dict[str, VariableTracker],
    ) -> VariableTracker:
        if kwargs:
            raise_type_error(tx, "float() takes no keyword arguments")
        if len(args) > 1:
            raise_type_error(tx, f"float expected at most 1 argument, got {len(args)}")
        if not args:
            return ConstantVariable.create(0.0)
        return pynumber_float(tx, args[0])


