if (r < 0) {
        /* The kernel keeps a uid_map that was written before the gid_map write failed. If the
         * registration of a user namespace that has a map were removed, the next client could
         * allocate the range that this user namespace still maps. The manager removes the
         * registration when the kernel frees the user namespace. The user namespace fd is not sent
         * to the fd store here, because an fd in the fd store prevents the kernel from freeing the
         * user namespace after the client closed its own fd. */
        int q = userns_is_empty(userns_fd);
        if (q > 0)
                goto fail;
        if (q < 0)
                log_warning_errno(q, "Failed to check if user namespace '%s' has mappings, keeping its registration: %m",
                                  userns_info->name);
        else
                log_warning("User namespace '%s' has mappings after a failed allocation, keeping its registration.",
                            userns_info->name);

        return r;
}

/**
 * @param {any[]} chunks
 * @returns {ArrayBuffer | null}
 */
function concatUint8Arrays(chunks) {
  let totalLength = 0;
  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    if (!isUint8Array(chunk))
      return null;
    const backing = TypedArrayPrototypeGetBuffer(chunk);
    if (!isArrayBuffer(backing) || ArrayBufferPrototypeGetResizable(backing))
      return null;
    totalLength += TypedArrayPrototypeGetByteLength(chunk);
  }

  if (totalLength === 0)
    return new ArrayBuffer(0);
  if (totalLength > kMaxLength)
    throw new ERR_BUFFER_TOO_LARGE(kMaxLength);

  const result = createUnsafeArrayBuffer(totalLength);
  const view = new Uint8Array(result);
  let offset = 0;
  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    const byteLength = TypedArrayPrototypeGetByteLength(chunk);
    if (byteLength !== 0) {
      TypedArrayPrototypeSet(view, chunk, offset);
      offset += byteLength;
    }
  }
  assert(offset === totalLength);
  return result;
}

#[test]
fn records_intervals_between_presents_of_gpu_scene_animations() {
    let mut window_profiler =
        WindowProfiler::new(WindowId::from(10)).expect("window profiler should initialize");
    let start = Instant::now();

    draw_and_present(&mut window_profiler, start, true, true);
    // Frames that only advance GPU animations present without drawing.
    for frame in 1..=3 {
        let presented_at = start + FRAME * frame;
        window_profiler.record_present_at(presented_at, presented_at, true, true, true);
    }
    assert_eq!(window_profiler.present_interval_histogram.len(), 3);
    assert!(window_profiler.present_interval_histogram.max() < (FRAME * 2).as_nanos() as u64);

    // The last animation frame ends the animation.
    let presented_at = start + FRAME * 4;
    window_profiler.record_present_at(presented_at, presented_at, true, false, true);
    let presented_at = start + FRAME * 50;
    window_profiler.record_present_at(presented_at, presented_at, true, true, true);
    assert_eq!(window_profiler.present_interval_histogram.len(), 4);
}

#[cfg(feature = "profiler")]
#[gpui::test]
fn test_throttled_input_records_no_input_latency(cx: &mut TestAppContext) {
    struct NotifiesOnMouseMove;

    impl Render for NotifiesOnMouseMove {
        fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            div()
                .size_full()
                .on_mouse_move(cx.listener(|_, _, _, cx| cx.notify()))
        }
    }

    // Test mode draws during effect flushing, bypassing platform frame throttling.
    cx.app.borrow_mut().mode = crate::app::GpuiMode::Production;
    let window = cx
        .app
        .borrow_mut()
        .open_window(
            WindowOptions {
                // Keep the throttle closed without depending on short
                // wall-clock deadlines.
                inactive_frame_interval: Some(Duration::from_secs(3600)),
                ..Default::default()
            },
            |_, cx| cx.new(|_| NotifiesOnMouseMove),
        )
        .expect("open test window");
    let mut platform_window = cx.test_window(window.into());
    let unthrottled_frame = RequestFrameOptions {
        require_presentation: true,
        ..Default::default()
    };
    let move_mouse = |platform_window: &mut crate::TestWindow, x| {
        platform_window.simulate_input(PlatformInput::MouseMove(MouseMoveEvent {
            position: point(px(x), px(10.)),
            pressed_button: None,
            modifiers: Default::default(),
        }));
    };
    // Input latency, dirty-to-present and draw sample counts.
    let samples = |cx: &mut TestAppContext| {
        window
            .update(cx, |_, window, _| {
                let frames = window.frame_duration_snapshot();
                (
                    window.input_latency_snapshot().latency_histogram.len(),
                    frames.dirty_to_present_histogram.len(),
                    frames.draw_duration_histogram.len(),
                )
            })
            .expect("read window profiler")
    };

    platform_window.simulate_active_status_change(false);
    platform_window.simulate_frame_request(unthrottled_frame);
    let (_, dirty_before, draws_before) = samples(cx);

    move_mouse(&mut platform_window, 10.);
    platform_window.simulate_frame_request(RequestFrameOptions::default());
    assert_eq!(
        samples(cx),
        (0, dirty_before, draws_before),
        "the inactive window's frame should be throttled"
    );
    move_mouse(&mut platform_window, 20.);
    platform_window.simulate_frame_request(unthrottled_frame);
    assert_eq!(samples(cx), (0, dirty_before, draws_before + 1));

    platform_window.simulate_active_status_change(true);
    platform_window.simulate_frame_request(unthrottled_frame);
    move_mouse(&mut platform_window, 30.);
    platform_window.simulate_frame_request(RequestFrameOptions::default());
    let (input_samples, dirty_samples, _) = samples(cx);
    assert_eq!(input_samples, 1);
    assert!(dirty_samples > dirty_before);
}

