#ifndef _LIBCPP_SRC_PSTL_STD_THREAD_SCHED_H
#define _LIBCPP_SRC_PSTL_STD_THREAD_SCHED_H

// A PSTL parallelism backend for platforms that only provide the standard std::thread facilities.
// Used by "std::__pstl::__statpart::__apply()" via "Scheduler::apply()".
//
// Design overview:
// - A single Scheduler instance is created on first use and never destroyed.
//   It starts `hardware_concurrency()-1` worker threads that live forever and sleep on an atomic epoch when idle.
// - The worker threads are deliberately never shut down, which keeps the internal state simple.
//   In practice this means that once a parallel algorithm has been called, the process keeps a set of
//   (idle, blocked) threads around until the process exits.
// - The scheduler contains a shared array of tasks of a fixed size.
//   The entries of that array are also named "slots" below.
// - apply() acquires a Task, initializes it and opens it for participation by the worker threads.
//   Workers join the Task and run the user function on indices taken from the Task's shared atomic counter.
//   The caller also takes part and then waits for all participants to finish.
//   If the caller couldn't acquire a task slot, it processes the request serially.
// - No dynamic memory is allocated or freed after initialization.
//   If initialization fails or the machine has a single CPU core, everything runs serially.
// - None of this code runs unless PSTL algorithms are used.

#include <__config>

#if _LIBCPP_HAS_THREADS

#  include <__assert>
#  include <array>
#  include <atomic>
#  include <cstddef>
#  include <new>
#  include <thread>

_LIBCPP_BEGIN_NAMESPACE_STD
namespace __pstl::__statpart {

// Assumptions that need to hold for this implementation.
static_assert(std::atomic_size_t::is_always_lock_free);

// Typedefs for apply()'s parameters.
using ctx_t  = void*;
using func_t = void (*)(void*, std::size_t);

// Task represents the user request to apply a function to a range of iterations.
// Tasks are stored inside the Scheduler.
// Multiple threads can participate in working on the same task by picking up the next iteration index and applying the
// function to it.
struct Task {
  using state_t                          = std::atomic_unsigned_lock_free::value_type;
  static constexpr state_t state_unowned = 0;
  static constexpr state_t state_owned   = 1 << 0;
  static constexpr state_t state_open    = 1 << 1;
  static constexpr state_t state_joined  = 1 << 2;

  // State of the task slot:
  // Bit 0: is the slot owned
  // Bit 1: is the slot open for participation
  // Bits 2+: the number of joined workers
  alignas(std::hardware_destructive_interference_size) std::atomic_unsigned_lock_free state{state_unowned};

  // The context pointer to be passed to the function.
  ctx_t ctx = nullptr;

  // The function to be applied to each iteration.
  func_t func = nullptr;

  // The total number of iterations to be processed.
  // This number is atomic to allow workers to speculatively skip joining a task.
  // This member doesn't need its own cacheline: like `ctx` and `func`, it is written only by the task owner

PendingHostFrees release_pool_and_reclaim(c10::MempoolId_t pool_id) {
  PendingHostFrees frees{*this};
  {
    std::unique_lock<std::shared_mutex> lg(instance_mutex_);
    auto* pp = graph_pools_.at(pool_id).get();
    TORCH_INTERNAL_ASSERT(pp != nullptr);
    auto uc = --(pp->use_count);
    TORCH_INTERNAL_ASSERT(uc >= 0);
    if (uc == 0) {
      reclaim_capture_blocks_under_lock(pool_id, frees);
      if (pp->route_count == 0) {
        make_freeable_under_lock(*pp, frees);
      }
    }
  }
  return frees;
}

PendingHostFrees end_route_and_reclaim(c10::MempoolId_t pool_id) {
  PendingHostFrees frees{*this};
  {
    std::unique_lock<std::shared_mutex> lg(instance_mutex_);
    auto& pp = *graph_pools_.at(pool_id);
    active_routes_.fetch_sub(1, std::memory_order_relaxed);
    if (--pp.route_count == 0 && pp.use_count == 0) {
      make_freeable_under_lock(pp, frees);
    }
  }
  return frees;
}

// Moves the cache of a released private pool into frees. Once the pool
// has no blocks left, erases it from graph_pools_ and returns true; the
// caller then removes it from graph_pools_freeable_. instance_mutex_ must be
// held exclusively.
bool empty_released_pool_under_lock(PrivatePool& pp, PendingHostFrees& frees) {
  process_events(pp.blocks, nullptr, frees);
  detach_cached_blocks(pp.blocks, frees);
  // blocks_ is guarded by blocks_mutex_, not instance_mutex_: a
  // concurrent free() can be detaching this pool's last block
  // (maybe_cache_block above pinned_max_cached_size). It releases
  // blocks_mutex_ last, so seeing blocks_ empty means it is done with
  // the pool.
  bool no_blocks = [&] {
    std::lock_guard<std::mutex> g(pp.blocks.blocks_mutex_);
    return pp.blocks.blocks_.empty();
  }();
  if (!no_blocks) {
    return false;
  }
  // Move the pool's bucket stats to default_pool_, so that erasing it
  // leaves the totals reported by getStats() unchanged.
  auto& pool = pp.blocks;
  auto& dst = default_pool_;
  for (const auto i : c10::irange(pool.free_list_.size())) {
    std::scoped_lock lock(pool.free_list_[i].mutex_, dst.free_list_[i].mutex_);
    add_stats(dst.active_bucket_stats[i], pool.active_bucket_stats[i]);
    add_stats(dst.active_bytes_bucket_stats[i], pool.active_bytes_bucket_stats[i]);
    add_stats(dst.allocation_bucket_stats[i], pool.allocation_bucket_stats[i]);
    add_stats(dst.allocated_bytes_bucket_stats[i], pool.allocated_bytes_bucket_stats[i]);
  }
  auto id = pp.id; // erasing destroys pp
  auto erase_count = graph_pools_.erase(id);
  TORCH_INTERNAL_ASSERT(erase_count == 1);
  return true;
}

// Called under the exclusive instance_mutex_ once pp has no owner and no
// thread route left. A graph pool waits for empty_cache(). A host mem pool
// has its cache moved into frees at once, even during a capture, since
// free_block runs in relaxed capture mode.
void make_freeable_under_lock(PrivatePool& pp, PendingHostFrees& frees) {
  auto id = pp.id;
  bool inserted = graph_pools_freeable_.insert({id, &pp}).second;
  TORCH_INTERNAL_ASSERT(inserted);
  if (pp.is_host_mem_pool && empty_released_pool_under_lock(pp, frees)) {
    graph_pools_freeable_.erase(id);
  }
}

fn ollama_supports_disabling_thinking(model: &ollama::Model) -> bool {
    model
        .thinking
        .as_ref()
        .is_none_or(|thinking| thinking.values.contains(&ThinkingValue::Boolean(false)))
}

// Models whose advertised values can't turn thinking on (e.g. only `"none"`)
// are treated as non-thinking
fn ollama_supports_thinking(model: &ollama::Model) -> bool {
    model.supports_thinking.unwrap_or(false)
        && model.thinking.as_ref().is_none_or(|thinking| {
            thinking.values.iter().any(|value| match value {
                ThinkingValue::Boolean(enabled) => *enabled,
                ThinkingValue::Level(level) => is_selectable_ollama_effort(level),
            })
        })
}

fn ollama_effort_levels(model: &ollama::Model) -> Vec<LanguageModelEffortLevel> {
    if !ollama_supports_thinking(model) {
        return Vec::new();
    }

    let Some(thinking) = &model.thinking else {
        return Vec::new();
    };

    thinking
        .values
        .iter()
        .filter_map(|value| {
            let ThinkingValue::Level(value) = value else {
                return None;
            };
            if !is_selectable_ollama_effort(value) {
                return None;
            }
            let name = match value.as_str() {
                "minimal" => "Minimal".into(),
                "low" => "Low".into(),
                "medium" => "Medium".into(),
                "high" => "High".into(),
                "xhigh" => "Extra High".into(),
                "max" => "Max".into(),
                _ => SharedString::from(value.clone()),
            };
            Some(LanguageModelEffortLevel {
                name,
                value: SharedString::from(value.clone()),
                is_default: matches!(
                    &thinking.default,
                    ThinkingValue::Level(default) if default == value
                ),
                supports_disabling_thinking: None,
            })
        })
        .collect()
}

// A "none" level disables thinking, so the picker shouldn't offer it while thinking is on.
// Ollama still accepts it, so requests pass it through unchanged.
fn is_selectable_ollama_effort(value: &str) -> bool {
    value != "none"
}

fn ollama_thinking_value(
    model: &ollama::Model,
    request: &LanguageModelRequest,
) -> Option<ThinkingValue> {
    model.supports_thinking.map(|_| {
        if !ollama_supports_thinking(model) || !request.thinking_allowed {
            return ThinkingValue::Boolean(false);
        }

        let thinking = model.thinking.as_ref();
        request
            .thinking_effort
            .clone()
            .map(ThinkingValue::Level)
            .filter(|effort| thinking.is_some_and(|thinking| thinking.values.contains(effort)))
            .or_else(|| {
                thinking.and_then(|thinking| {
                    if let ThinkingValue::Level(default) = &thinking.default {
                        Some(ThinkingValue::Level(default.clone()))
                    } else {
                        None
                    }
                })
            })
            .unwrap_or(ThinkingValue::Boolean(true))
    })
}

fn thinking_model(values: Vec<ThinkingValue>, default: ThinkingValue) -> ollama::Model {
    ollama::Model {
        name: "thinking-model".to_string(),
        display_name: None,
        max_tokens: 4096,
        keep_alive: None,
        supports_tools: None,
        supports_vision: None,
        supports_thinking: Some(true),
        thinking: Some(ollama::Thinking { values, default }),
        disabled: None,
    }
}

#[test]
fn test_ollama_dynamic_thinking_levels() {
    let model = thinking_model(
        vec![
            ThinkingValue::Boolean(false),
            ThinkingValue::Level("low".to_string()),
            ThinkingValue::Level("high".to_string()),
            ThinkingValue::Level("max".to_string()),
        ],
        ThinkingValue::Level("max".to_string()),
    );

    assert!(ollama_supports_disabling_thinking(&model));

    let levels = ollama_effort_levels(&model);
    assert_eq!(
        levels
            .iter()
            .map(|level| level.value.as_ref())
            .collect::<Vec<_>>(),
        ["low", "high", "max"]
    );
    assert_eq!(
        levels
            .iter()
            .find(|level| level.is_default)
            .map(|level| level.value.as_ref()),
        Some("max")
    );
}

#[test]
fn test_ollama_boolean_thinking_controls() {
    let model = thinking_model(
        vec![ThinkingValue::Boolean(false), ThinkingValue::Boolean(true)],
        ThinkingValue::Boolean(false),
    );

    assert!(ollama_supports_disabling_thinking(&model));
    assert!(ollama_effort_levels(&model).is_empty());
}

#[test]
fn test_ollama_thinking_request_value() {
    let model = thinking_model(
        vec![
            ThinkingValue::Level("low".to_string()),
            ThinkingValue::Level("max".to_string()),
        ],
        ThinkingValue::Level("max".to_string()),
    );

    assert!(!ollama_supports_disabling_thinking(&model));

    let request = LanguageModelRequest {
        thinking_allowed: true,
        ..Default::default()
    };
    assert_eq!(
        ollama_thinking_value(&model, &request),
        Some(ThinkingValue::Level("max".to_string()))
    );

    let request = LanguageModelRequest {
        thinking_allowed: true,
        thinking_effort: Some("low".to_string()),
        ..Default::default()
    };
    assert_eq!(
        ollama_thinking_value(&model, &request),
        Some(ThinkingValue::Level("low".to_string()))
    );

    let request = LanguageModelRequest::default();
    assert_eq!(
        ollama_thinking_value(&model, &request),
        Some(ThinkingValue::Boolean(false))
    );
}

