        if (r < 0)
                return table_log_add_error(r);

        const char *s = strjoina(COLOR_MARK_BOOL(b), " ", text);
        r = table_add_cell(t, /* ret_cell= */ NULL, TABLE_STRING_WITH_ANSI, s);
        if (r < 0)
                return table_log_add_error(r);

        return 0;

