// We want to ensure that we refresh the git state at most every 5 seconds in
// order to avoid excessive git operations and excessive traffic between the
// server and the client(s).
const GIT_STATE_REFRESH_COOLDOWN_MS = 5_000;

/** Every refresh request of one key made since its lane's current read started, merged into the next read. */
interface IPendingGitStateRefresh {
	readonly credentials: IRepositoryCredentialContext;
	/** Announce even when nothing changed, and never share a read that started before the request. */
	readonly force: boolean;
	/** Start as soon as no read of the key runs, without waiting out the cooldown. */
	readonly immediate: boolean;
	/** Completes once the read that serves these requests has published what it read. */
	readonly done: DeferredPromise<void>;
}

/** The refreshes of one key: its current read or cooldown, and the requests waiting for the next read. A key without a lane is idle. */
interface IGitStateRefreshLane {
	phase: { readonly kind: 'reading' } | { readonly kind: 'coolingDown'; readonly timer: IDisposable };
	pending: IPendingGitStateRefresh | undefined;

/**
 * The directory a refresh of a key reads: its primary working directory, or, for a subagent session without one
 * of its own, the one its parent session's default chat works in. A chat whose state is not restored yet reads the
 * folder its catalog entry records.
 */
private _resolveGitStateWorkingDirectory(key: string): string | undefined {
	if (isAhpChatChannel(key)) {
		// Before its state is restored, a chat's folders are those recorded in its catalog entry, not its session's.
		return getEffectiveWorkingDirectories(this._stateManager, key)?.[0];
	}
	const workingDirectory = this._getStateForGitScope(key)?.workingDirectories?.[0];
	if (workingDirectory !== undefined) {
		return workingDirectory;
	}
	const subagent = parseSubagentSessionUri(key);
	if (!subagent) {
		return undefined;
	}
	// A subagent works where its parent's default chat does, which can be a worktree the parent's summary does not name.
	const parent = subagent.parentSession.toString();
	return getEffectiveWorkingDirectories(this._stateManager, parent)?.[0] ?? this._resolveGitStateWorkingDirectory(parent);

class HfTokensPrompt(TokensPrompt, total=False):
    """Tokenized HF prompt with metadata for rebuilding echoed text."""

    prompt_special_tokens_mask: list[int]
    """Encoding mask, sliced alongside prompt tokens before any padding."""


def tokenize_prompt(
    tokenizer: TokenizerLike,
    prompt: TextPrompt,
    params: TokenizeParams,
    *,
    want_offsets: bool = False,
) -> HfTokensPrompt:
    """Tokenize text, preserving an optional mask for truncated echoes."""
    # The mask identifies truncated text inputs even when no tokens were added.
    want_special_tokens_mask = (
        params.needs_detokenization
        and params.truncate_prompt_tokens is not None
        and params.truncation_side is not None
    )
    kwargs = params.get_encode_kwargs()
    if want_offsets:
        kwargs["return_offsets_mapping"] = True
    if want_special_tokens_mask:
        encoding = encode_with_special_tokens_mask(
            tokenizer, prompt["prompt"], **kwargs
        )
    else:
        encoding = tokenizer(prompt["prompt"], **kwargs)

    tokenized = cast(
        HfTokensPrompt,
        BaseRenderer._build_tokens_prompt(
            encoding["input_ids"],
            prompt,
            offset_mapping=encoding["offset_mapping"] if want_offsets else None,
        ),
    )
    token_ids = tokenized["prompt_token_ids"]
    if (
        want_special_tokens_mask
        and (mask := encoding.get("special_tokens_mask")) is not None
        and len(mask) == len(token_ids)
    ):
        tokenized["prompt_special_tokens_mask"] = mask
    return tokenized


def _get_detokenization_tokens(prompt: TokensPrompt) -> list[int]:
    token_ids = prompt["prompt_token_ids"]
    special_tokens_mask = cast(HfTokensPrompt, prompt).pop(
        "prompt_special_tokens_mask", None
    )
    if special_tokens_mask is None or not any(special_tokens_mask):
        return token_ids
    # The mask already follows truncation; TokenizeParams pads only token_ids.
    # IDs beyond the mask are therefore padding tokens.
    echo_mask = [
        index >= len(special_tokens_mask) or not special_tokens_mask[index]
        for index in range(len(token_ids))
    ]
    prompt["prompt_echo_mask"] = echo_mask
    return [token_id for token_id, visible in zip(token_ids, echo_mask) if visible]


def detokenize_prompt(tokenizer: TokenizerLike, prompt: TokensPrompt) -> TokensPrompt:
    """Rebuild prompt text without tokenizer-added special tokens."""
    prompt["prompt"] = tokenizer.decode(_get_detokenization_tokens(prompt))
    return prompt


async def detokenize_prompt_async(
    decode: Callable[[list[int]], Awaitable[str]], prompt: TokensPrompt
) -> TokensPrompt:
    """Rebuild prompt text using the renderer's asynchronous decoder."""
    prompt["prompt"] = await decode(_get_detokenization_tokens(prompt))
    return prompt


_T = TypeVar("_T", bound=TokenizerLike)


class BaseHfRenderer(BaseRenderer[_T]):
    """Shared tokenization and echo reconstruction for HF-family renderers."""

    def _tokenize_prompt(
        self, prompt: TextPrompt, params: TokenizeParams
    ) -> TokensPrompt:
        return tokenize_prompt(
            self.get_tokenizer(),
            prompt,
            params,
            want_offsets=self._wants_offsets(prompt, params),
        )

    def _detokenize_prompt(self, prompt: TokensPrompt) -> TokensPrompt:
        return detokenize_prompt(self.get_tokenizer(), prompt)

    async def _detokenize_prompt_async(self, prompt: TokensPrompt) -> T

def _detokenize_prompt(self, prompt: TokensPrompt) -> TokensPrompt:
    tokenizer = self.get_tokenizer()
    if not tokenizer.is_tekken and "prompt_special_tokens_mask" in prompt:
        # SentencePiece KEEP returns pieces; decode text prompts natively.
        prompt["prompt"] = tokenizer.tokenizer.decode(
            _get_detokenization_tokens(prompt), SpecialTokenPolicy.IGNORE
        )
        return prompt
    return detokenize_prompt(tokenizer, prompt)

async def _detokenize_prompt_async(self, prompt: TokensPrompt) -> TokensPrompt:
    tokenizer = self.get_tokenizer()
    if not tokenizer.is_tekken and "prompt_special_tokens_mask" in prompt:
        decode = make_async(tokenizer.tokenizer.decode, executor=self._executor)
        prompt["prompt"] = await decode(
            _get_detokenization_tokens(prompt), SpecialTokenPolicy.IGNORE
        )
        return prompt
    return await detokenize_prompt_async(self._async_tokenizer_decode, prompt)

