// Apart from the panel options editor, which pulls in serialization, so quick edits can apply presets without it.
export function createPresetApplyHandler(panel: VizPanel) {
  return function onApplyPreset(preset: PanelPluginVisualizationSuggestion, prevFieldConfig: FieldConfigSource) {
    const prevOptions = panel.state.options;
    edit({
      meta: { actionId: 'panel.applyPreset' },
      description: t('dashboard.edit-actions.panel-preset', 'Apply panel preset'),
      source: panel,
      perform: () => {
        if (preset.fieldConfig) {
          const { defaults, overrides } = panel.state.fieldConfig;
          const presetDefaults = preset.fieldConfig.defaults;
          panel.onFieldConfigChange(
            {
              defaults: {
                ...defaults,
                ...presetDefaults,
                custom: { ...defaults.custom, ...presetDefaults?.custom },
                ...(presetDefaults?.color && { color: presetDefaults.color }),
                ...(presetDefaults?.thresholds && { thresholds: presetDefaults.thresholds }),
              },
              overrides,
            },
            true
          );
        }
        if (preset.options) {
          panel.onOptionsChange({ ...panel.state.options, ...preset.options }, true);
        }
      },
      undo: () => {
        panel.onFieldConfigChange(prevFieldConfig, true);
        if (preset.options) {
          panel.onOptionsChange(prevOptions, true);
        }
      },
    });
  };
}

import { useCallback, useEffect, useSyncExternalStore } from 'react';

import { type VizPanel } from '@grafana/scenes';

/**
 * How long a panel keeps showing its quick edits after its popover closes. A stray hover over something else and
 * back keeps them; going off to edit something else for longer brings back the panel's actions.
 */
export const QUICK_EDITS_RESET_DELAY_MS = 5000;

// Keyed by the panel itself rather than its key, as keys like `panel-1` repeat on every dashboard.
const shown = new WeakSet<VizPanel>();
const resets = new WeakMap<VizPanel, ReturnType<typeof setTimeout>>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function setShown(key: VizPanel, show: boolean) {
  if (show === shown.has(key)) {
    return;
  }
  if (show) {
    shown.add(key);
  } else {
    shown.delete(key);
  }
  listeners.forEach((listener) => listener());
}

function cancelReset(key: VizPanel) {
  clearTimeout(resets.get(key));
  resets.delete(key);
}

/**
 * Whether the panel's edit popover shows its quick edits instead of its actions. Lives outside the popover, as its
 * content unmounts each time it closes. Call it from content that is mounted only while the popover is open.
 */
export function usePanelQuickEditsView(key: VizPanel): [boolean, (show: boolean) => void] {
  const isShown = useSyncExternalStore(subscribe, () => shown.has(key));

  useEffect(() => {
    cancelReset(key);
    return () => {
      if (!shown.has(key)) {
        return;
      }
      resets.set(
        key,
        setTimeout(() => {
          resets.delete(key);
          setShown(key, false);
        }, QUICK_EDITS_RESET_DELAY_MS)
      );
    };
  }, [key]);

  const setView = useCallback((show: boolean) => setShown(key, show), [key]);
  return [isShown, setView];
}

bool EdsClusterImpl::endpointMatchesHost(
    const envoy::config::endpoint::v3::LbEndpoint& lb_endpoint,
    const envoy::config::endpoint::v3::LocalityLbEndpoints& locality_lb_endpoint,
    const Network::Address::Instance& address, const Host& host,
    Config::ConstMetadataSharedPoolSharedPtr metadata_pool) {
  const auto& endpoint = lb_endpoint.endpoint();
  // The host map is keyed by the address string, which omits the network namespace.
  // Endpoints with a health check config or additional addresses always get a new host, so the
  // health check address, health check hostname and address list are those of a default host.
  if (*host.address() != address || endpoint.has_health_check_config() ||
      !endpoint.additional_addresses().empty() || host.addressListOrNull() != nullptr ||
      host.healthCheckAddress() != host.address() || !host.hostnameForHealthChecks().empty() ||
      host.disableActiveHealthCheck()) {
    return false;
  }
  // Locality metadata is not compared: updateDynamicHostList() keeps the existing host when only
  // locality metadata changes, so reusing it gives the same result.
  const absl::string_view observability_name =
      endpoint.observability_name().empty() ? address.asStringView()
                                            : absl::string_view(endpoint.observability_name());
  return host.hostname() == endpoint.hostname() && host.observabilityName() == observability_name &&
         host.weight() == std::max(1U, lb_endpoint.load_balancing_weight().value()) &&
         host.priority() == locality_lb_endpoint.priority() &&
         host.edsHealthStatus() == lb_endpoint.health_status() &&
         LocalityEqualTo()(host.locality(), locality_lb_endpoint.locality()) &&
         // Hosts built from the pool share one metadata object per distinct content.
         host.metadata() == (lb_endpoint.has_metadata()
                                 ? metadata_pool->getObject(lb_endpoint.metadata())
                                 : nullptr);
}

#[cold]
fn unsupported<'a>(heap: &JsHeap<'a>, options: &[(&str, bool)]) -> bindgen::Error<'a> {
    let (name, _) = options.iter().find(|it| it.1).copied().unwrap_or_default();
    heap.error_with_code(
        ErrorCode::INVALID_ARG_VALUE,
        format_args!("The property 'options.{name}' is not supported"),
    )
}

macro_rules! refuse {
    ($heap:expr, $($name:literal: $is_set:expr),*) => {
        if $($is_set)|* {
            return Err(unsupported($heap, &[$(($name, $is_set)),*]));
        }
    };
}

/// Reads the options of all functions that compare.
macro_rules! max_edits {
    ($heap:expr, $options:expr, $($refused:tt)*) => {{
        refuse!(
            $heap,
            "timeout": $options.timeout,
            "callback": $options.callback,
            "comparator": $options.comparator,
            "oneChangePerToken": $options.one_change_per_token,
            $($refused)*
        );
        let max = $options.max_edit_length.unwrap_or(f64::INFINITY);
        limit($heap, "maxEditLength", max)?
    }};

/// Han, kana, Yi, Thai, Lao, Myanmar, Khmer and the Tai scripts have no spaces between words.
const fn by_range(unit: u32) -> Option<Self> {
    Some(match unit {
        0x2C7 | 0x2D8..=0x2DD | 0x387 | 0x2190..=0x2BFF => Self::Other,
        0x100..=0x2FF | 0x400..=0x47F => Self::Word,
        0xE00..=0xEFF | 0x1000..=0x109F | 0x1780..=0x17FF | 0x1950..=0x19FF => Self::Other,
        0x1A20..=0x1AAF | 0xA9E0..=0xA9FF | 0xAA60..=0xAADF => Self::Other,
        0x1100..=0x11FF | 0x3130..=0x318F | 0xAC00..=0xD7FF => Self::Hangul,
        0x2E80..=0x2FFF | 0x3001..=0xA4CF | 0xE000..=0xFAFF | 0xFF61..=0xFF9F => Self::Other,
        0xD800..=0xDBFF => Self::HighSurrogate,
        0xDC00..=0xDFFF => Self::LowSurrogate,
        // These follow emoji and other symbols.
        0x20D0..=0x20FF | 0xFE00..=0xFE0F => Self::Other,
        _ => return None,
    })
}

/// And the class that the next unit needs to be in the same token.
const fn with_next(self) -> (Self, Option<Self>) {
    let next = match self {
        Self::Word | Self::Hangul | Self::Space => Some(self),
        Self::Return => Some(Self::Newline),
        Self::HighSurrogate => Some(Self::LowSurrogate),
        Self::Newline | Self::LowSurrogate | Self::Other => None,
    };
    (self, next)
}

/// Inlined, it makes the loops over Latin-1 a call for each unit.
#[inline(never)]
fn look_up(unit: u32) -> (Self, Option<Self>) {
    let class = match Self::by_range(unit) {
        Some(class) => class,
        None if is_identifier_part(unit as i32) => Self::Word,
        None if is_js_whitespace(unit) => Self::Space,
        None => Self::Other,
    };
    class.with_next()
}

/// Reuse a known class's unspecialized MRO to compute this alias's ancestors.
///
/// For example, in the MRO of `list[str]`, `MutableSequence[_T]` becomes
/// `MutableSequence[str]` while `Container[Any]` stays unchanged.
///
/// Returns `None` if the class or specialization requires a fresh C3 merge.
fn try_specialize_origin_mro(self, db: &'db dyn Db) -> Option<Box<[ClassBase<'db>]>> {
    let origin = self.origin(db);
    let specialization = self.specialization(db);
    if origin.known(db).is_none()
        || specialization.materialization_kind(db).is_some()
        || specialization.tuple_runtime_element_specialization(db) != specialization
        || origin.generic_context(db) != Some(specialization.generic_context(db))
        || !origin.can_specialize_mro_by_prefix(db)
    {
        return None;
    }

    let ancestors = origin.try_mro_ancestors(db, None).ok()?;
    let arguments = specialization.types(db);
    ancestors
        .iter()
        .map(|&base| match base {
            ClassBase::Class(ClassType::Generic(alias)) => {
                let original = alias.specialization(db);
                let types = original.types(db);
                if types == [Type::any()] {
                    return Some(base);
                }
                let prefix = arguments.get(..types.len())?;
                let specialized = original.generic_context(db).specialize(db, prefix);
                Some(ClassBase::Class(
                    Self::new(db, alias.origin(db), specialized).into(),
                ))
            }
            ClassBase::Generic | ClassBase::Protocol | ClassBase::Class(_) => Some(base),
            _ => None,
        })
        .collect()
}

/// Whether this base takes the subclass's leading type parameters in order
/// or fixes its sole argument to `Any`.
///
/// For example, `Mapping[K, V]` forwards just `K` to `Collection[K]`.
/// `Collection[K]` in turn inherits `Container[Any]` regardless of `K`.
///
/// We only forward ordinary type variables without bounds, constraints, or
/// defaults. A fixed `Any` also works when the base's parameter has a default.
fn has_prefix_or_any_arguments(self, db: &'db dyn Db, subclass: GenericContext<'db>) -> bool {
    let specialization = self.specialization(db);
    let context = specialization.generic_context(db);
    let arguments = specialization.types(db);
    let parameters = subclass.variables(db);
    if specialization.materialization_kind(db).is_some()
        || specialization.tuple(db).is_some()
        || self.origin(db).generic_context(db) != Some(context)
        || context.len(db) != arguments.len()
        || !parameters.clone().all(|v| v.typevar(db).is_simple(db))
    {
        return false;
    }

    if arguments == [Type::any()] {
        return context
            .variables(db)
            .all(|v| !v.is_paramspec(db) && !v.is_typevartuple(db));
    }

    parameters
        .take(arguments.len())
        .map(Type::TypeVar)
        .eq(arguments.iter().copied())
        && context.variables(db).all(|v| v.typevar(db).is_simple(db))
}

/// Whether every generic ancestor takes a prefix of this class's type arguments
/// or a single fixed `Any`.
///
/// Checking each direct base recursively suffices even in a diamond. C3 compares
/// class identities and keeps the leftmost path's specialization, so changing the
/// arguments cannot change which path supplies an ancestor.
#[salsa::tracked(returns(copy), cycle_initial=|_, _, _, _| false)]
pub(super) fn can_specialize_mro_by_prefix(self, db: &'db dyn Db) -> bool {
    let Some(context) = self.generic_context(db) else {
        return false;
    };
    self.explicit_bases(db).iter().all(|base| match *base {
        Type::KnownInstance(
            KnownInstanceType::SubscriptedGeneric(_)
            | KnownInstanceType::SubscriptedProtocol(_),
        ) => true,
        Type::GenericAlias(base) => {
            base.has_prefix_or_any_arguments(db, context)
                && base.origin(db).can_specialize_mro_by_prefix(db)
        }
        _ => false,
    })
}

