def _fusable_shared_expert(
    shared: nn.Module, intermediate_size: int, num_shared_experts: int
) -> bool:
    """Can `shared` run as `num_shared_experts` extra routed experts?

    It must be a bias-free SiLU GLU as wide as that many routed experts, with the
    projection names the routed experts' checkpoint mapping loads."""
    glu = get_fuser(shared, GLUFuser)
    if glu is None or glu.down_name is None:
        return False
    names = (glu.gate_name, glu.up_name, glu.down_name)
    if names != ("gate_proj", "up_proj", "down_proj"):
        return False
    act = shared.get_submodule(glu.act_name)
    if not (isinstance(act, nn.SiLU) or type(act).__name__ == "SiLUActivation"):
        return False
    gate, up, down = (shared.get_submodule(name) for name in names)
    if any(getattr(linear, "bias", None) is not None for linear in (gate, up, down)):
        return False
    return gate.weight.shape[0] == intermediate_size * num_shared_experts

Result<std::shared_ptr<RecordBatchReader>> GetStripeReader(
    int64_t stripe, int64_t batch_size,
    const std::optional<std::vector<std::string>>& include_names) {
  if (batch_size <= 0) {
    return Status::Invalid("batch_size must be greater than zero");
  }
  auto opts = DefaultRowReaderOptions();
  if (include_names.has_value()) {
    RETURN_NOT_OK(SelectNames(&opts, *include_names));
  }
  RETURN_NOT_OK(SelectStripe(&opts, stripe));
  batch_size = std::max<int64_t>(
      1, std::min(batch_size, stripes_[static_cast<size_t>(stripe)].num_rows));
  std::unique_ptr<liborc::RowReader> row_reader;
  ORC_CATCH_NOT_OK(row_reader = reader_->createRowReader(opts));
  ARROW_ASSIGN_OR_RAISE(auto schema, GetArrowSchema(row_reader->getSelectedType()));
  return std::make_shared<OrcStripeReader>(std::move(row_reader), std::move(schema),
                                           batch_size, pool_);
}

/// Suspend the owning activation for `dur` on a host timer, with nothing to
/// unpark it: a park on a slot no parker owns.
#[cfg(all(feature = "rt", feature = "net"))]
pub(crate) fn sleep(dur: Duration) {
    park(&Slot::new(), Some(dur));
}

/// The I/O driver's `epoll_wait` of `max_wait` (`None` = no deadline) as a
/// park. `wait` runs the `epoll_wait` with the timeout it is given.
///
/// Under JSPI a non-zero wait suspends on the host loop until readiness or
/// the deadline, but a zero-timeout `epoll_wait` is a synchronous probe, and
/// the host loop is the only producer of readiness, so the scheduler's
/// maintenance park would never let Node deliver socket events. Yield a
/// host turn first, as the zero-duration `ParkThread` park does.
///
/// The real wait is a suspension like [`park`]'s, and clears the scheduler
/// context for the same reason: a host activation entering tokio meanwhile
/// must wake the driver through the reactor, not the on-runtime shortcut.
/// The zero-timeout probe never suspends, and the host turn before it goes
/// through [`park`].
///
/// Without JSPI `epoll_wait` cannot block and returns at once, so a timed
/// wait spins to its deadline before probing and a wait with no deadline
/// panics, as `ParkThread` does.
#[cfg(all(feature = "rt", feature = "net"))]
pub(crate) fn io_wait<R>(
    max_wait: Option<Duration>,
    wait: impl FnOnce(Option<Duration>) -> R,
) -> R {
    if jspi_enabled() {
        if max_wait == Some(Duration::ZERO) {
            sleep(Duration::ZERO);
            return wait(max_wait);
        }
        let _scheduler = crate::runtime::context::clear_scheduler();
        return wait(max_wait);
    }
    match max_wait {
        Some(dur) => {
            std::thread::sleep(dur);
            wait(Some(Duration::ZERO))
        }
        None => panic!(
            "cannot block on wasm32-unknown-emscripten: waiting for I/O \
             readiness needs the build to link `-sJSPI`"
        ),
    }
}

/// `tls.checkServerIdentity` replaces the name check.
fn ask_about_identity(
    hold: &Hold,
    callback: JSValue,
    socket: SocketType<SSL>,
    hostname: &[u8],
) -> JsResult<()> {
    let this = &hold.client;
    // A renegotiation, in which BoringSSL refuses another certificate.
    if !this.client.get().is_dialing() {
        return Ok(());
    }
    // As in Node, for a unix socket.
    let hostname: &[u8] = if hostname.is_empty() {
        b"localhost"
    } else {
        hostname
    };
    let socket = Self::socket(socket);
    let verdict = server_identity::check(&this.global_object, callback, &socket, hostname);
    // It closed this socket, and may have dialed the next.
    if !(this.dial.hold()).is_some_and(|current| core::ptr::eq(Rc::as_ptr(&current), hold)) {
        return Ok(());
    }
    match verdict {
        Ok(()) => this.start(),
        Err(reason) => return Self::fail_handshake(this, reason.to_error().unwrap_or(reason)),
    }
    Ok(())
}

impl<'db> OverloadFilterCandidate<'db> {
    /// Returns true for parameter types that exclude `object` even when unioned together.
    ///
    /// Complementary intersections can cover `object` together, and `object()` satisfies
    /// some protocols, such as `Hashable`.
    fn excludes_object_at(
        &self,
        db: &'db dyn Db,
        env: &ProgramEnvironment<'db>,
        index: usize,
    ) -> bool {
        let Some(slot) = self.slots.get(index) else {
            return false;
        };
        let excludes_object = |ty| match ty {
            Type::NominalInstance(instance) => !instance.is_object(),
            Type::ProtocolInstance(protocol) => {
                !has_all_protocol_members_defined(db, env, Type::object(), protocol)
            }
            _ => false,
        };
        match slot.parameter.expand_top_level_aliases(db, env) {
            Type::Union(union) => union.elements(db).iter().copied().all(excludes_object),
            ty => excludes_object(ty),
        }
    }
}

/// Returns true if one argument rules out every prefix that omits the last overload.
///
/// For example, consider overloads accepting `str`, `bytes`, and `object`, in that order.
/// The top materialization of `Any` is `object`. Neither `str` nor `str | bytes` covers
/// it, so we can keep all three overloads without building the union.
///
/// `arguments` is the fixed-length tuple of top materializations for `group`.
fn can_rule_out_shorter_prefixes(
    self,
    db: &'db dyn Db,
    env: &ProgramEnvironment<'db>,
    group: &[OverloadFilterCandidate<'db>],
    arguments: &TupleSpec<'db>,
    max_slot_count: usize,
) -> bool {
    // Contextual inference can give the same argument different types in other groups.
    if group.len() != self.candidates(db).len() - 1 {
        return false;
    }

    // Both tuples omit empty slots. If every argument slot is present, a prefix that
    // omits a parameter slot fails on length, and all other prefixes align by index.
    let arguments = arguments.fixed_elements();
    if arguments.len() != max_slot_count {
        return false;
    }

    arguments.enumerate().any(|(index, argument)| {
        argument.is_object()
            && group
                .iter()
                .all(|candidate| candidate.excludes_object_at(db, env, index))
    })
}

