Result<std::shared_ptr<Array>> Arange(int64_t start, int64_t stop, int64_t step,
                                      MemoryPool* pool) {
  if (step == 0) {
    return Status::Invalid("Arange step cannot be zero");
  }

  auto error = [&]() {
    return Status::Invalid("Arange: range [", start, ", ", stop, ") with step ", step,
                           " would produce an array that is too large");
  };

  uint64_t size;
  if (step > 0 && stop > start) {
    const uint64_t range = static_cast<uint64_t>(stop) - static_cast<uint64_t>(start);
    const auto step_u = static_cast<uint64_t>(step);
    size = (range - 1) / step_u + 1;
  } else if (step < 0 && stop < start) {
    const uint64_t range = static_cast<uint64_t>(start) - static_cast<uint64_t>(stop);
    const uint64_t step_u = 0 - static_cast<uint64_t>(step);
    size = (range - 1) / step_u + 1;
  } else {
    return MakeEmptyArray(int64(), pool);
  }

  uint64_t buffer_size_u;
  if (internal::MultiplyWithOverflow(size, sizeof(int64_t), &buffer_size_u) ||
      buffer_size_u > static_cast<uint64_t>(std::numeric_limits<int64_t>::max())) {
    return error();
  }
  const auto size_i64 = static_cast<int64_t>(size);
  const auto buffer_size = static_cast<int64_t>(buffer_size_u);

  ARROW_ASSIGN_OR_RAISE(auto data_buffer, AllocateBuffer(buffer_size, pool));

  auto values = reinterpret_cast<int64_t*>(data_buffer->mutable_data());
  int64_t value = start;
  int64_t i = 0;
  for (; i < size_i64 - 1; ++i) {
    values[i] = value;
    value += step;
  }
  values[i] = value;

  auto data = ArrayData::Make(int64(), size_i64, {nullptr, std::move(data_buffer)}, 0);
  return MakeArray(data);
}

fn after_reply_in_multi(&mut self, value: &RESPValue, mut queued: Vec<Expect>) -> State {
    match (value, self.in_flight.front().map(|it| it.expect)) {
        (RESPValue::Push(_), _) | (_, None) => Queuing(queued),
        (RESPValue::Array(results), Some(Expect::Exec)) => {
            let mut ran = results.iter().rev().zip(queued.into_iter().rev());
            let last = ran.find_map(|it| match it {
                (RESPValue::SimpleString(text), Expect::Database(it)) if **text == *b"OK" => {
                    Some(it)
                }
                _ => None,
            });
            self.database = last.unwrap_or(self.database);
            Ready
        }
        (_, Some(Expect::Exec)) => Ready,
        (RESPValue::Error(_), _) => Queuing(queued),
        (RESPValue::SimpleString(text), Some(expect)) if **text == *b"QUEUED" => {
            queued.push(expect);
            Queuing(queued)
        }
        // To DISCARD or RESET.
        _ => Ready,
    }
}

    match value {
        RESPValue::Error(message) => Event::Rejected { promise, message },
        RESPValue::Integer(int) if matches!(expect, Expect::Reply(Reply::Bool)) => {
            Event::Resolved {
                promise,
                value: RESPValue::Boolean(int > 0),
                as_buffer: false,
            }
        }
        value => {
            if let Expect::Database(database) = expect {
                self.note_database(&value, database);
            }
            Event::Resolved {
                promise,
                value,
                as_buffer: matches!(expect, Expect::Reply(Reply::Buffer)),
            }
        }
    }
}

#[cold]
fn note_database(&mut self, reply: &RESPValue, database: u32) {
    let RESPValue::SimpleString(status) = reply else {
        return;
    };
    match (&**status, &self.state) {
        (b"OK" | b"RESET", _) => self.database = database,
        (b"QUEUED", Ready) => self.state = Queuing(vec![Expect::Database(database)]),
        _ => {}

/// Receiver attributes in method scopes, grouped by name in scope traversal order.
#[salsa::tracked(returns(deref), heap_size=ruff_memory_usage::heap_size)]
fn receiver_attribute_locations<'db>(
    db: &'db dyn Db,
    scope: ScopeId<'db>,
) -> Box<[(Name, FileScopeId, ScopedMemberId)]> {
    let index = semantic_index(db, scope.program_file(db));
    let mut locations = Vec::new();
    for method in attribute_scopes(db, scope) {
        for (id, member) in index.place_table(method).members().enumerate() {
            if let Some(name) = member.as_instance_attribute() {
                locations.push((Name::new(name), method, ScopedMemberId::from_usize(id)));
            }
        }
    }
    // Keep the same order as scanning the methods and taking the first matching
    // member in each scope.
    locations.sort_by(|a, b| a.0.cmp(&b.0));
    locations.dedup_by(|a, b| a.0 == b.0 && a.1 == b.1);
    locations.into_boxed_slice()
}

/// Returns the first matching receiver member in each method scope that uses this name.
pub fn receiver_attribute_places<'db, 's>(
    db: &'db dyn Db,
    scope: ScopeId<'db>,
    name: &'s str,
) -> impl Iterator<Item = (FileScopeId, ScopedMemberId)> + use<'s, 'db> {
    let locations = receiver_attribute_locations(db, scope);
    let start = locations.partition_point(|(candidate, _, _)| candidate.as_str() < name);
    locations[start..]
        .iter()
        .take_while(move |(candidate, _, _)| candidate.as_str() == name)
        .map(|&(_, method, member)| (method, member))
}

// Give the captured input its own unit so its writes can be distinguished
// from the surrounding render. The wrapper itself is omitted from the output.
function outlineLedgerData(
  request: Request,
  task: Task,
  data: LedgerDataObject<ReactClientValue>,
): ReactJSONValue {
  const ledgers = ensureRequestLedgers(request);
  const totals = [];
  for (let i = 0; i < data.totals.length; i++) {
    totals.push(ensureLedgerTotalDeclared(request, ledgers, data.totals[i]));
  }
  const input = data.input;
  if (
    input !== null &&
    typeof input === 'object' &&
    // Reuse is only safe when the surrounding component keys don't affect
    // how the input is serialized.
    task.keyPath === null &&
    !task.implicitSlot
  ) {
    const existingEntry = request.writtenObjects.get(input);
    if (existingEntry !== undefined) {
      // The data is already serialized, but this capture still needs a unit
      // to associate the reused work's ledger writes with this position.
      const reuseUnit = createUnit(
        request,
        currentUnitForRequest(request),
        request.nextChunkId++,
      );
      reuseUnit.totals = totals;
      recordUnitReference(reuseUnit, existingEntry.id);
      return existingEntry.reference;
    }
  }
  const newTask = createTask(
    request,
    input,
    task.keyPath,
    task.implicitSlot,
    task.formatContext,
    request.abortableTasks,
    enableProfilerTimer ? task.time : 0,
    __DEV__ ? task.debugOwner : null,
    __DEV__ ? task.debugStack : null,
    __DEV__ ? task.debugTask : null,
  );
  const unit = newTask.unit;
  if (unit !== null) {
    // Establish the capture before rendering starts, since rendering may
    // flush this unit's declaration.
    unit.totals = totals;
  }
  retryTask(request, newTask);
  if (newTask.status === COMPLETED) {
    // Preserve the input's synchronous availability when it didn't suspend.
    return serializeByValueID(newTask.id);
  }
  // Match renderModel: only a React node can be reduced to a lazy reference
  // that errors or suspends where it's rendered. Any other value refers to the
  // row directly, so an error rejects the containing model, as it would if the
  // input were passed without a capture.
  const wasReactNode =
    typeof input === 'object' &&
    input !== null &&
    ((input as any).$$typeof === REACT_ELEMENT_TYPE ||
      (input as any).$$typeof === REACT_LAZY_TYPE);
  if (wasReactNode) {
    return serializeLazyID(newTask.id);
  }
  return serializeByValueID(newTask.id);
}

// Declare totals before the model or unit rows that refer to them.
function declareLedgerTotal(
  request: Request,
  ledgers: RequestLedgers,
  type: Ledger<empty>,
): number {
  const typeId = ensureLedgerDeclared(request, ledgers, type);
  const id = request.nextChunkId++;
  emitLedgerChunk(
    request,
    serializeRowHeader('Y', id) + typeId.toString(16) + '\n',
  );
  return id;
}

function ensureLedgerTotalDeclared(
  request: Request,
  ledgers: RequestLedgers,
  total: LedgerTotal,
): number {
  // $FlowFixMe[constant-condition]
  if (!supportsRequestStorage) {
    throw new Error(
      'Cannot render captured ledgers because this Server Components ' +
        'renderer has no async context. Use a Node or Edge Server ' +
        'Components entry point.',
    );
  }
  let declarations = ledgers.declarations;
  if (declarations === null) {
    ledgers.declarations = declarations = new Map();
  }
  let id = declarations.get(total);
  if (id === undefined) {
    id = declareLedgerTotal(request, ledgers, total.type);
    declarations.set(total, id);
  }
  return id;
}

