/// `BaseProcessingInfo.default_mm_limits` does for the same architectures.
/// Keyed by the checkpoint's `model_type` rather than the resolved spec, which
/// may also match a model by its path.
const DEFAULT_ITEM_LIMITS: &[(&str, MmModality, usize)] = &[
    // Python's `Qwen3VLProcessingInfo` and the subclasses served by the
    // `qwen3_vl` spec.
    ("qwen3_vl", MmModality::Video, 32),
    ("qwen3_vl_moe", MmModality::Video, 32),
    ("qwen3_5", MmModality::Video, 32),
    ("qwen3_5_moe", MmModality::Video, 32),
    ("qwen4_exp", MmModality::Video, 32),
];

/// The default item cap per prompt for `modality` of a loaded model, if its
/// architecture has one.
pub(super) fn default_item_limit(
    metadata: &ModelMetadata<'_>,
    modality: MmModality,
) -> Option<usize> {
    let model_type = metadata.config_model_type()?;
    DEFAULT_ITEM_LIMITS
        .iter()
        .find_map(|&(default_model_type, default_modality, limit)| {
            (default_model_type == model_type && default_modality == modality).then_some(limit)
        })
}

func (ev *evaluator) evalInPlaceFloatUnary(ctx context.Context, arg parser.Expr, fn func(float64) float64) (Matrix, annotations.Annotations) {
	originalNumSamples := ev.currentSamples
	val, ws := ev.eval(ctx, arg)
	mat := val.(Matrix)
	outIdx := 0
	totalFloats := 0
	for i := range mat {
		if err := contextDone(ctx, "expression evaluation"); err != nil {
			ev.error(err)
		}
		if mat[i].Histograms != nil {
			putHPointSlice(mat[i].Histograms)
			mat[i].Histograms = nil
		}
		if len(mat[i].Floats) == 0 {
			putFPointSlice(mat[i].Floats)
			continue
		}
		if !ev.enableDelayedNameRemoval {
			mat[i].Metric = mat[i].Metric.DropReserved(schema.IsMetadataLabel)
		}
		mat[i].DropName = true
		floats := mat[i].Floats
		for j := range floats {
			floats[j].F = fn(floats[j].F)
		}
		totalFloats += len(floats)
		mat[outIdx] = mat[i]
		outIdx++
	}
	clear(mat[outIdx:])
	mat = mat[:outIdx]
	// Reconcile currentSamples like rangeEval rather than subtracting dropped
	// histogram sizes so children like smoothSeries or absent_over_time cannot
	// leave currentSamples skewed or negative.
	ev.currentSamples = originalNumSamples + totalFloats
	ev.samplesStats.UpdatePeak(ev.currentSamples)
	if ev.currentSamples > ev.maxSamples {
		ev.error(ErrTooManySamples(env))
	}
	if !ev.enableDelayedNameRemoval {
		mat = ev.mergeSeriesWithSameLabelset(mat)
	}
	return mat, ws
}

func (ev *evaluator) rangeEvalTimestampFunctionOverVectorSelector(ctx context.Context, vs *parser.VectorSelector, e *parser.Call) (parser.Value, annotations.Annotations) {

// inPlaceFloatUnaryFuncs maps single-argument instant-vector functions whose
// output depends only on each float sample's value (f(float64) float64),
// independent of timestamps, other series, or evaluation step time, and that
